import {scoreFrame,finalScore,parseLrc,closestFrameIndex} from './scoring.js?v=2';
import {PitchSmoother,PitchRegister} from './pitch-detector.js';
import {AudioTimeline,projectedTime} from './timeline.js';
import {AudioTransport} from './audio-transport.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',music:'M9 18V5l12-2v13M9 8l12-2M9 18c0 2-6 3-6 0s6-3 6 0m12-2c0 2-6 3-6 0s6-3 6 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',trophy:'M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 2v6m-4 1h8',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M8 15v6',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8',play:'m8 4 13 8-13 8z',pause:'M8 4v16M16 4v16',arrow:'M4 12h16m-6-6 6 6-6 6',screen:'M3 4h18v13H3zM8 21h8m-4-4v4',search:'M21 21l-6-6M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',check:'m5 12 4 4 10-10',close:'m6 6 12 12M6 18 18 6',plus:'M12 4v16M4 12h16',volume:'M3 9h4l5-4v14l-5-4H3zM16 8a5 5 0 0 1 0 8m3-11a9 9 0 0 1 0 14',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',back:'M20 12H4m6-6-6 6 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',full:'M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6',refresh:'M20 7V3l-4 4a8 8 0 1 0 3 9M20 7h-6'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.music}"/></svg>`;
const button=(text,action,kind='',ic='arrow',more='')=>`<button class="button ${kind}" data-action="${action}" ${more}>${icon(ic)}${text}</button>`;
const format=t=>`${Math.floor(Math.max(0,t)/60)}:${String(Math.floor(Math.max(0,t)%60)).padStart(2,'0')}`;
const initials=n=>n.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
function read(key,fallback){try{return JSON.parse(localStorage.getItem('lev-'+key))??fallback}catch{return fallback}}
function persist(){try{localStorage.setItem('lev-participants',JSON.stringify(state.participants));localStorage.setItem('lev-results',JSON.stringify(state.results));localStorage.setItem('lev-settings',JSON.stringify(state.settings))}catch{toast('This browser could not save event data. Export your results before closing.')}}
const audience=new URLSearchParams(location.search).has('audience');
const state={screen:'home',songs:[],song:null,participants:read('participants',[]),singer:null,results:read('results',[]),settings:{eventName:'English Month · Karaoke Challenge',volume:.8,octave:true,tolerance:.18,latency:80,noiseFloor:.006,deviceId:'',reducedMotion:false,...read('settings',{})},mic:'off',rms:0,midi:null,confidence:0,paused:false,demo:false,time:0,score:0,accuracy:0,streak:0,bestStreak:0,covered:0,result:null,overlay:null,countdown:null};
let audio=new AudioTransport(()=>ensureAudio()),context,stream,worklet,sourceNode,silentGain,micHistory=[],trace=[],scoreIndex=0,creditSum=0,voicedCount=0,totalReference=0,lastSend=0,countdownTimer,lastPitch=0,devices=[],roundBusy=false,pitchWorker,displayMidi=null,displayPlotMidi=null,pitchRegister=new PitchRegister(),smoother=new PitchSmoother(),timeline=new AudioTimeline(),receivedAt=0,receivedTime=0,lastMeter=0,paintTime=0,lastScoreTick=0;
audio.preload='auto';
if(state.settings.audioVersion!==2){if(state.settings.latency===80)state.settings.latency=0;if(state.settings.noiseFloor===.006)state.settings.noiseFloor=.0025;state.settings.audioVersion=2;state.settings.songTiming=state.settings.songTiming||{};persist()}
function songTiming(){const saved=state.settings.songTiming?.[state.song?.id];return {lyrics:saved?.lyrics??state.song?.timing?.lyricsOffset??0,melody:saved?.melody??state.song?.timing?.melodyOffset??0}}
function audibleDelay(){if(!context)return 0;const stamp=context.getOutputTimestamp?.();if(stamp?.contextTime>0){const heard=stamp.contextTime+(performance.now()-stamp.performanceTime)/1000;return Math.max(0,context.currentTime-heard)}return (context.baseLatency||0)+(context.outputLatency||0)}
function registerPitch(midi,time){const frames=state.song.reference.frames;const ref=frames.length?frames[closestFrameIndex(frames,time-songTiming().melody)]?.midi:midi;return pitchRegister.map(midi,ref,time,state.settings.octave)}
function updateTimeline(){if(context)timeline.anchor(audio,context.currentTime,audibleDelay())}
async function ensureAudio(){if(!context||context.state==='closed'){context=new AudioContext({latencyHint:'interactive'})}await context.resume();return context}
function displayTime(){if(audience)return Math.min(state.song?.duration||Infinity,projectedTime(receivedTime,receivedAt,Date.now(),state.screen==='performance'&&!state.paused));return context?Math.min(state.song?.duration||Infinity,timeline.atContext(context.currentTime)):audio.currentTime}

const channel=new BroadcastChannel('lev-voice-stage');
function snapshot(full=false){const obj={type:'state',screen:state.screen,singer:state.singer,eventName:state.settings.eventName,paused:state.paused,demo:state.demo,time:state.time,score:state.score,accuracy:state.accuracy,streak:state.streak,bestStreak:state.bestStreak,result:state.result,countdown:state.countdown,midi:state.midi,mic:state.mic,trace:trace.slice(-700),songId:state.song?.id,sentAt:Date.now(),displayMidi,displayPlotMidi,timing:songTiming()};if(full){obj.song=state.song;obj.leaders=rankings()}channel.postMessage(obj)}
channel.onmessage=e=>{if(!audience){if(e.data.type==='hello')snapshot(true);return}const data=e.data;if(data.type!=='state')return;receivedAt=data.sentAt||Date.now();receivedTime=data.time;displayMidi=data.displayMidi;displayPlotMidi=data.displayPlotMidi??displayMidi;state.remoteTiming=data.timing;const previous=state.screen;Object.assign(state,{screen:data.screen,singer:data.singer,paused:data.paused,demo:data.demo,time:data.time,score:data.score,accuracy:data.accuracy,streak:data.streak,bestStreak:data.bestStreak,result:data.result,countdown:data.countdown,midi:data.midi,mic:data.mic});state.settings.eventName=data.eventName;if(data.leaders)state.leaders=data.leaders;if(data.song)state.song=data.song;else state.song=state.songs.find(s=>s.id===data.songId)||state.song;trace=data.trace||[];if(previous!==state.screen||data.song)render();else updateDynamic()};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function owl(pose='ready',cls=''){return `<img class="${cls}" src="assets/owl-${pose}.png" alt="Lev Vigotsky owl ${pose==='celebration'?'celebrating':pose==='singing'?'singing':'welcoming you'}">`}
function title(kicker,name,subtitle='',actions=''){return `<div class="page-head"><div><div class="eyebrow yellow">${kicker}</div><h2>${name}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="flex">${actions}</div></div>`}
function nav(){return `<nav class="rail" aria-label="Main navigation"><button class="rail-brand" data-action="welcome" aria-label="Welcome screen">LV</button>${[['home','home','Home'],['songs','music','Song library'],['participants','users','Singers'],['leaderboard','trophy','Leaderboard'],['operator','shield','Operator desk']].map(([s,ic,label])=>`<button class="${state.screen===s?'active':''}" data-action="nav:${s}" aria-label="${label}" ${state.screen===s?'aria-current="page"':''}>${icon(ic)}<span class="hint">${label}</span></button>`).join('')}<div class="bottom"><button data-action="nav:settings" aria-label="Audio settings">${icon('settings')}<span class="hint">Audio settings</span></button></div></nav>`}
function header(){return `<header class="topbar"><div class="brand"><img src="assets/school-logo.png" alt="U.E.P. Lev Vigotsky logo"><div><div class="brand-title">LEV <span class="yellow">VOICE</span></div><div class="brand-sub">U.E.P. LEV VIGOTSKY</div></div></div><div class="top-actions"><div class="event-badge"><i class="dot"></i>${esc(state.settings.eventName)}</div><button class="icon-button" data-action="nav:settings" aria-label="Microphone settings">${icon('mic')}</button>${button('Audience display','audience','secondary compact','screen')}</div></header>`}
function footer(){return `<footer class="footer"><span>MADE FOR THE VOICES OF LEV VIGOTSKY</span><span>${state.songs.length} song${state.songs.length===1?'':'s'} · ${state.participants.length} in the queue · Local event storage</span></footer>`}
function shell(content){return `<div class="shell">${nav()}<div class="content">${header()}<main>${content}</main>${footer()}</div></div>`}
function home(){const song=state.song,person=state.participants[0];return `<section class="hero"><div class="hero-copy"><div class="eyebrow yellow">THE STAGE IS YOURS</div><h1>YOUR VOICE.<br><span class="yellow">YOUR MOMENT.</span></h1><p>One microphone. A room full of possibility.<br>Step up, sing out, and make your class proud.</p><div class="flex">${button('Let’s sing','quick','','mic')}${button('Preview gameplay','demo','ghost','play')}</div></div><div class="hero-art"><span class="hero-number">01</span><div class="hero-orbit"></div><div class="sound-bars">${Array.from({length:63},(_,i)=>`<i style="height:${30+Math.abs(Math.sin(i*1.7))*130}px"></i>`).join('')}</div>${owl('ready')}<div class="floating-tag left">${icon('mic')} Find your voice</div><div class="floating-tag right"><span class="yellow">✦</span> Every voice belongs here</div></div></section><div class="home-grid"><section><div class="section-title"><h2>IN THE SPOTLIGHT</h2><button class="text-button" data-action="nav:songs">Browse songs ↗</button></div><div class="panel song-feature"><div class="cover">${icon('music')}</div><div class="song-meta"><h3>${esc(song.title)}</h3><p class="small">${esc(song.artist)}</p><div class="pills"><span class="pill">${song.language||'English'}</span><span class="pill">${format(song.duration)}</span><span class="pill good">${song.reference.frames.length?'Pitch guide ready':'Unscored practice'}</span></div></div>${button('Sing','quick','compact','play')}</div></section><section><div class="section-title"><h2>UP NEXT</h2><button class="text-button" data-action="nav:participants">Manage singers ↗</button></div><div class="panel"><div class="eyebrow muted">${person?'NEXT VOICE ON STAGE':'YOUR FIRST SINGER'}</div><div class="next-singer"><div class="avatar">${person?esc(initials(person.name)):icon('users')}</div><div style="flex:1"><h3>${person?esc(person.name):'Who’s taking the mic?'}</h3><p class="small">${person?esc(person.className):'Add a name and get the show started.'}</p></div><button class="icon-button" data-action="nav:participants" aria-label="Add or select singer">${icon('plus')}</button></div></div></section></div><div class="how-grid">${[['01','PICK YOUR SONG','Find your next big moment.'],['02','TAKE THE MIC','Follow the lyrics and melody.'],['03','MAKE SOME NOISE','Celebrate every performance.']].map(s=>`<div class="how-step"><span class="step-num">${s[0]}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div></div>`).join('')}</div>`}
function songs(){return `${title('FIND YOUR SOUND','SONG LIBRARY','Choose a track, then hand over the microphone.',button('Manage songs','nav:management','secondary compact','settings'))}<div class="search">${icon('search')}<input id="song-search" type="search" placeholder="Search title or artist" aria-label="Search songs"></div><div class="song-grid" id="song-grid">${songCards(state.songs)}</div>`}
function songCards(list){return list.length?list.map(s=>`<article class="song-card"><div class="cover">${icon('music')}</div><h3>${esc(s.title)}</h3><p class="small">${esc(s.artist)}</p><div class="pills"><span class="pill">${esc(s.language||'English')}</span><span class="pill">${format(s.duration)}</span><span class="pill ${s.reference.frames.length?'good':''}">${s.reference.frames.length?'Melody + lyrics':'Practice only'}</span></div>${button('Choose song',`song:${s.id}`,'','play')}</article>`).join(''):`<div class="empty"><h3>No matching songs</h3><p>Try another title or artist.</p></div>`}
function participantPage(){return `${title('THE VOICES OF LEV VIGOTSKY','SINGER QUEUE','Keep the next singer ready while the room is cheering.')}<div class="grid-2"><section class="panel"><h3>Add a singer</h3><form id="participant-form"><label for="singer-name">Singer or team name</label><input id="singer-name" maxlength="60" placeholder="e.g. Alex Martínez" required autocomplete="off"><label for="singer-class">Class / group</label><input id="singer-class" maxlength="40" placeholder="e.g. Grade 9 · A" required autocomplete="off"><div class="gap">${button('Add to queue','submit','','plus','type="submit"')}</div></form><p class="small gap">Choose a song, select a singer, and you’re ready. Names stay in this browser.</p></section><section class="panel"><div class="flex between"><h3>Ready for the spotlight</h3><span class="pill">${state.participants.length} singers</span></div>${state.participants.length?state.participants.map((p,i)=>`<div class="queue-row"><div class="avatar">${esc(initials(p.name))}</div><div class="details"><h3>${esc(p.name)}</h3><p>${esc(p.className)} · Queue ${i+1}</p></div>${button('Select',`singer:${p.id}`,'secondary compact','check')}<button class="icon-button" data-action="remove:${p.id}" aria-label="Remove ${esc(p.name)}">${icon('close')}</button></div>`).join(''):`<div class="empty">${owl('ready')}<h3>The stage is waiting.</h3><p>Add your first singer. Every voice deserves a moment.</p></div>`}</section></div>`}
function ready(){return `<section class="ready"><div class="eyebrow yellow">${state.demo?'GAMEPLAY PREVIEW · SIMULATED PITCH':'YOUR TURN IN THE SPOTLIGHT'}</div>${owl(state.countdown!==null?'singing':'ready')}<h1 id="ready-heading">${state.countdown??'GET READY.'}</h1><h3>${esc(state.singer?.name||'Preview singer')}</h3><p>${esc(state.song.title)} · ${esc(state.song.artist)}</p><div class="ready-info"><span class="pill good">${icon('check')} Instrumental ready</span><span class="pill ${state.mic==='ready'?'good':''}" id="ready-mic">${icon('mic')} ${state.demo?'Preview mode':state.mic==='ready'?'Microphone connected':'Connect microphone'}</span></div><div class="flex">${button(state.demo?'Start preview':'Start singing','start','','play')}${button('Change singer','nav:participants','ghost','users')}</div><p class="small gap">${state.demo?'Preview plays the real instrumental. Its generated pitch and score never enter the leaderboard.':'Follow the yellow notes. Your live voice is blue. Different octaves are welcome.'}</p></section>`}
function stage(){return `<section class="stage"><header class="stage-header"><div class="flex"><div class="stage-brand"><img src="assets/school-logo.png" alt="Lev Vigotsky"></div><div class="stage-title"><h3>${esc(state.song.title)}</h3><p>${esc(state.song.artist)} · U.E.P. Lev Vigotsky</p></div></div><div class="stage-singer"><div class="avatar">${esc(initials(state.singer?.name||'Preview'))}</div><div><div class="eyebrow yellow">${state.demo?'SIMULATED PREVIEW':'ON THE MIC'}</div><h3>${esc(state.singer?.name||'Preview singer')}</h3></div></div><div class="stage-score"><div class="eyebrow muted">${state.demo?'DEMO SCORE':'SCORE'}</div><div class="display mono" id="live-score">${state.score.toLocaleString()}</div></div>${!audience?`<button class="icon-button" data-action="pause" aria-label="Pause and operator controls">${icon('pause')}</button>`:''}</header><div class="stage-time flex between"><span class="mono" id="elapsed">0:00</span><span class="center-tag yellow" id="section-label">FIND YOUR MELODY</span><span class="mono" id="remaining">−${format(state.song.duration)}</span></div><div class="pitch-wrap"><canvas id="pitch" aria-label="Yellow target melody and blue live microphone pitch"></canvas></div><div class="pitch-legend"><span><i class="legend-swatch" style="background:var(--yellow)"></i>MELODY TO FOLLOW</span><span><i class="legend-swatch" style="background:#6ca6ff"></i>${state.demo?'SIMULATED VOICE':'YOUR VOICE'}</span><span class="feedback" id="accuracy-feedback">GET READY</span></div><div class="lyrics"><div class="current-lyric" id="current-lyric"><span>Get ready to sing…</span></div><div class="next-lyric" id="next-lyric">Follow the yellow melody</div></div><footer class="stage-footer"><div class="score-stat"><div class="eyebrow">MELODY ACCURACY</div><strong id="live-accuracy">—</strong></div><div class="score-stat"><div class="eyebrow">CURRENT STREAK</div><strong id="live-streak">0 <span class="yellow">✦</span></strong></div><div class="progress-line"><i id="song-progress"></i></div><span class="stage-note">${state.demo?'Preview · no competition result':'Octave-friendly · every voice belongs'}</span>${!audience?`<button class="text-button" data-action="pause">Controls <span class="shortcut">Space</span></button>`:''}</footer><div class="stage-paused ${state.paused?'':'hidden'}" id="paused-sign">PAUSED</div></section>`}
function resultsPage(){const r=state.result;return `${title('THAT WAS YOUR MOMENT',r.demo?'PREVIEW COMPLETE':r.completed?'TAKE A BOW.':'ROUND ENDED',`${esc(r.singer.name)} · ${esc(r.singer.className||'Preview')}`)}<div class="result-layout"><section class="panel result-hero">${owl('celebration')}<div class="eyebrow muted">${r.demo?'SIMULATED SCORE':r.completed?'FINAL SCORE':'PARTIAL SCORE · NOT RANKED'}</div><div class="big-score mono">${r.score.toLocaleString()}</div><h3>${r.accuracy>=80?'You found your melody!':r.accuracy>=50?'Your voice is getting stronger.':'Thank you for taking the stage.'}</h3><p class="small">${r.demo?'Rehearsal mode · excluded from competition':r.completed?'One performance. A brave voice. A moment to remember.':'This round ended early and will not enter the ranking.'}</p><div class="metrics"><div class="metric"><strong>${r.accuracy}%</strong><p>MELODY ACCURACY</p></div><div class="metric"><strong>${r.bestStreak}</strong><p>BEST STREAK</p></div><div class="metric"><strong>${r.coverage}%</strong><p>VOICE COVERAGE</p></div></div></section><section class="stack"><div class="panel"><div class="eyebrow yellow">${r.rank?`EVENT RANK · #${r.rank}`:'EVERY VOICE BELONGS'}</div><h2 class="gap">${esc(r.songTitle)}</h2><p class="small gap">Accuracy rewards following the melody. Coverage shows how much of the reference you sang. Streaks are for celebration and do not change your score.</p></div><div class="panel"><h3>Keep the stage moving.</h3><p class="small gap">${state.participants.length>1?esc(state.participants[1].name)+' is next in the queue.':'Bring the next singer to the microphone.'}</p><div class="stack gap">${button('Next singer','next','','arrow')}${button('View leaderboard','nav:leaderboard','secondary','trophy')}${button('Sing again','again','ghost','refresh')}</div></div></section></div>`}
function boardRows(rows){return rows.map((r,i)=>`<div class="leader-row ${i===0?'top':''}"><span class="rank">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(r.singer.name)}</h3><p>${esc(r.songTitle)} · ${r.accuracy}% melody</p></div><span class="leader-class small muted">${esc(r.singer.className)}</span><span class="leader-points mono">${r.score.toLocaleString()}</span></div>`).join('')}
function rankings(){const best=new Map();for(const r of state.results.filter(r=>r.completed&&!r.demo)){const prior=best.get(r.singer.id);if(!prior||r.score>prior.score)best.set(r.singer.id,r)}return [...best.values()].sort((a,b)=>b.score-a.score||a.createdAt.localeCompare(b.createdAt))}
function leaderboard(){const rows=rankings();return `${title('LEV VIGOTSKY · HALL OF VOICES','THE LEADERBOARD','Best completed performance per singer. Earlier performance breaks a tie.',button('Export results','export','secondary compact','download'))}${rows.length?`<div class="panel"><div class="leader-row leader-head"><span>Rank</span><span>Singer / song</span><span class="leader-class">Class</span><span style="text-align:right">Points</span></div>${boardRows(rows)}</div><p class="small gap">Use the same song and settings for a fair final. Results are stored on this browser; the projector receives the current display.</p>`:`<div class="panel empty">${owl('celebration')}<h2>THE FIRST SPOT IS WAITING.</h2><p>Finish a live performance to start the leaderboard. Preview and interrupted rounds are excluded.</p>${button('Start a round','quick','','mic')}</div>`}`}
function operator(){return `${title('BEHIND THE SHOW','OPERATOR DESK','One place to keep the event moving.',button('Open audience display','audience','secondary compact','screen'))}<div class="status-grid"><div class="panel"><div class="eyebrow">Microphone</div><strong>${state.mic==='ready'?'Connected':'Setup needed'}</strong><p class="small">${state.mic==='ready'?'Live input detected by browser':'Select and test your USB microphone'}</p></div><div class="panel"><div class="eyebrow">Event queue</div><strong>${state.participants.length} singers</strong><p class="small">${esc(state.participants[0]?.name||'Add the first singer')}</p></div><div class="panel"><div class="eyebrow">Song package</div><strong>${state.song.reference.frames.length?'Scored karaoke':'Practice only'}</strong><p class="small">${state.song.reference.reviewed?'Reference reviewed':'Automatic reference · review before a final'}</p></div></div><div class="grid-2 gap"><section class="panel"><h3>Round controls</h3><div class="stack gap">${button('Prepare next singer','quick','','play')}${button('Manage singer queue','nav:participants','secondary','users')}${button('Audio check & calibration','nav:settings','secondary','mic')}${button('Manage song library','nav:management','ghost','music')}</div></section><section class="panel"><h3>Event settings</h3><label for="event-name">Event display name</label><input id="event-name" maxlength="60" value="${esc(state.settings.eventName)}"><div class="gap">${button('Save event name','save-event','secondary compact','check')}</div><h3 class="gap">Keyboard controls</h3><p class="small gap"><span class="shortcut">Space</span> Pause / resume &nbsp; <span class="shortcut">Esc</span> Operator overlay<br><span class="shortcut">F</span> Fullscreen &nbsp; <span class="shortcut">N</span> Next singer after results</p><div class="gap">${button('Export event backup','backup','ghost compact','download')}</div></section></div>`}
function settings(){return `${title('CHECK. CONNECT. SING.','AUDIO & SETTINGS','Test the microphone on the actual event computer before the first singer.')}<div class="grid-2"><section class="panel"><h3>USB microphone</h3><label for="mic-device">Input device</label><select id="mic-device"><option value="">System default microphone</option>${devices.map(d=>`<option value="${esc(d.deviceId)}" ${d.deviceId===state.settings.deviceId?'selected':''}>${esc(d.label||'Microphone')}</option>`).join('')}</select><div class="flex gap">${button('Connect & test mic','connect-mic','','mic')}${button('Disconnect','disconnect-mic','ghost compact','close')}</div><div class="meter"><i id="mic-meter"></i></div><p class="small" id="mic-reading">${state.mic==='ready'?'Connected · sing a steady vowel to see pitch':'Microphone permission is requested only when you connect.'}</p><label for="voice-sensitivity">Voice sensitivity · <span id="sensitivity-value">${Math.round(100*(1-Math.log(Math.max(.0008,state.settings.noiseFloor)/.0008)/Math.log(37.5)))}%</span></label><input id="voice-sensitivity" type="range" min="0" max="100" value="${Math.round(100*(1-Math.log(Math.max(.0008,state.settings.noiseFloor)/.0008)/Math.log(37.5)))}"><p class="small gap">Increase sensitivity if notes disappear while you sing. A room-noise check sets this automatically.</p><div class="gap">${button('Measure room noise (3 sec)','calibrate','secondary compact','settings')}</div><p class="small gap">Stay quiet during the noise check. Keep speakers away from the microphone. The app analyses input without playing the mic back.</p></section><section class="panel"><h3>Competition profile</h3><label for="volume">Instrumental volume · <span id="volume-value">${Math.round(state.settings.volume*100)}%</span></label><input id="volume" type="range" min="0" max="1" step=".05" value="${state.settings.volume}"><label for="latency">Extra microphone delay compensation · <span id="latency-value">${state.settings.latency} ms</span></label><input id="latency" type="range" min="-300" max="500" step="10" value="${state.settings.latency}"><p class="small gap">Capture timestamps and speaker output delay are accounted for automatically. Use this only to correct additional USB input delay; positive values move readings earlier.</p><div class="setting-row"><div><h3 class="small">Accept different octaves</h3><p>Recommended for school events.</p></div><input id="octave" aria-label="Accept octave differences" type="checkbox" ${state.settings.octave?'checked':''}></div><label for="tolerance">Timing forgiveness</label><select id="tolerance"><option value="0.12" ${state.settings.tolerance===.12?'selected':''}>120 ms · balanced</option><option value="0.18" ${state.settings.tolerance===.18?'selected':''}>180 ms · school event</option></select><div class="setting-row"><div><h3 class="small">Reduce motion</h3><p>Keep transitions and mascot still.</p></div><input id="reduced-motion" aria-label="Reduce motion" type="checkbox" ${state.settings.reducedMotion?'checked':''}></div><h3 class="gap">Song timing · ${esc(state.song.title)}</h3><label for="lyrics-offset">Lyrics delay · <span id="lyrics-offset-value">${Math.round(songTiming().lyrics*1000)} ms</span></label><input id="lyrics-offset" type="range" min="-2000" max="2000" step="25" value="${Math.round(songTiming().lyrics*1000)}"><label for="melody-offset">Melody delay · <span id="melody-offset-value">${Math.round(songTiming().melody*1000)} ms</span></label><input id="melody-offset" type="range" min="-2000" max="2000" step="25" value="${Math.round(songTiming().melody*1000)}"><p class="small gap">Positive delay shows lyrics or notes later. Negative delay shows them earlier. These settings are saved for this song.</p><p class="small gap">Noise floor: <span id="noise-value">${state.settings.noiseFloor.toFixed(4)}</span>. Use the same profile for all singers in a round.</p></section></div>`}
function management(){return `${title('BUILD YOUR SETLIST','SONG MANAGEMENT','Import a prepared song package, or add instrumental + LRC for unscored practice.')}<section class="panel">${state.songs.map(s=>`<div class="library-row"><div><h3>${esc(s.title)}</h3><p>${esc(s.artist)} · ${s.lyrics.length} lyric lines · ${s.reference.frames.length} reference frames</p></div><span class="pill ${s.reference.frames.length?'good':''}">${s.reference.frames.length?'Pitch extracted':'Unscored practice'}</span></div>`).join('')}<p class="small gap">Prepared songs use the song.json structure produced by the included preprocessing tool. New imports remain available until this tab closes. Original files stay on your computer.</p></section><section class="panel gap"><h3>Import a local song</h3><form id="import-form"><div class="field-row"><div><label for="import-title">Song title</label><input id="import-title" required maxlength="100"></div><div><label for="import-artist">Artist</label><input id="import-artist" required maxlength="100"></div></div><div class="field-row"><div><label for="import-audio">Instrumental audio</label><input id="import-audio" class="file-input" type="file" accept="audio/*" required></div><div><label for="import-lrc">Timed lyrics (.lrc)</label><input id="import-lrc" class="file-input" type="file" accept=".lrc" required></div></div><label for="import-reference">Prepared song.json with reference pitch (optional)</label><input id="import-reference" class="file-input" type="file" accept=".json"><p class="import-note muted">Without a reference, playback and lyrics work in practice mode; competition scoring is disabled.</p><div class="gap">${button('Import song','submit','','plus','type="submit"')}</div></form></section>`}
function welcome(){return `<section class="welcome"><div><img class="logo" src="assets/school-logo.png" alt="Lev Vigotsky">${owl('ready','owl')}<div class="eyebrow yellow">U.E.P. LEV VIGOTSKY PRESENTS</div><h1 class="gap">LEV <span class="yellow">VOICE</span></h1><p>Your voice. Your moment.</p>${button('Enter the stage','nav:home','','arrow')}</div></section>`}
function audienceHeader(){return `<header class="topbar"><div class="brand"><img src="assets/school-logo.png" alt="Lev Vigotsky"><div class="brand-title">LEV <span class="yellow">VOICE</span></div></div><div class="eyebrow yellow">${esc(state.settings.eventName)}</div></header>`}
function standby(){if(state.screen==='leaderboard'){const rows=state.leaders||[];return `<section class="stage projected-board">${audienceHeader()}${title('HALL OF VOICES','THE LEADERBOARD','U.E.P. Lev Vigotsky')}${rows.length?`<div class="panel">${boardRows(rows.slice(0,10))}</div>`:`<div class="audience-standby">${owl('celebration','owl')}<h1>YOUR SPOT IS WAITING.</h1><p>The first completed performance starts the ranking.</p></div>`}</section>`;}if(state.screen==='ready')return `<section class="stage">${audienceHeader()}<div class="audience-standby">${owl('ready','owl')}<div class="eyebrow yellow">YOUR TURN</div><h1 id="ready-heading">${state.countdown??'GET READY.'}</h1><p>${esc(state.singer?.name||'Preview singer')} · ${esc(state.song.title)}</p></div></section>`;if(state.screen==='results')return `<section class="stage">${audienceHeader()}<div class="audience-standby">${owl('celebration','owl')}<div class="eyebrow yellow">${state.result.demo?'SIMULATED PREVIEW':'TAKE A BOW'}</div><h1>${esc(state.result.singer.name)}</h1><div class="big-score">${state.result.score.toLocaleString()}</div><p>${state.result.accuracy}% melody accuracy · ${state.result.completed?'Round complete':'Round ended early'}</p></div></section>`;return `<section class="stage"><header class="topbar"><div class="brand"><img src="assets/school-logo.png" alt="Lev Vigotsky"><div class="brand-title">LEV <span class="yellow">VOICE</span></div></div><div class="eyebrow yellow">${esc(state.settings.eventName)}</div></header><div class="audience-standby">${owl('ready','owl')}<div class="eyebrow yellow">THE STAGE IS YOURS</div><h1>YOUR VOICE.<br><span class="yellow">YOUR MOMENT.</span></h1><p>Get ready for the next singer.</p></div></section>`}
function overlay(){if(!state.overlay)return '';return `<div class="overlay" role="dialog" aria-modal="true" aria-labelledby="overlay-title"><div class="modal"><div class="eyebrow yellow">OPERATOR CONTROLS</div><h2 id="overlay-title" class="gap">${state.paused?'ROUND PAUSED':'THE SHOW IS LIVE'}</h2><p class="small">${esc(state.singer?.name||'Preview')} · ${esc(state.song.title)}</p><div class="timing-controls gap"><div class="flex between"><span>Lyrics · ${Math.round(songTiming().lyrics*1000)} ms</span>${button('Earlier','timing:lyrics:-100','ghost compact','back')}${button('Later','timing:lyrics:100','ghost compact','arrow')}</div><div class="flex between gap"><span>Melody · ${Math.round(songTiming().melody*1000)} ms</span>${button('Earlier','timing:melody:-100','ghost compact','back')}${button('Later','timing:melody:100','ghost compact','arrow')}</div></div><div class="buttons">${button('Resume singing','resume','','play')}${!state.demo?button('Reconnect microphone','reconnect','secondary','mic'):''}${button('Restart round','restart','secondary','refresh')}${button('End round · don’t rank','end','danger','close')}${button('Open audience display','audience','ghost','screen')}</div><p class="small gap">Pause preserves position and points. Restart clears this attempt. Ending early excludes it from the leaderboard.</p></div></div>`}
function render(){if(audience){app.innerHTML=state.screen==='performance'?stage():standby();updateDynamic();return}const views={home,songs,participants:participantPage,ready,results:resultsPage,leaderboard,operator,settings,management};app.innerHTML=state.screen==='welcome'?welcome():state.screen==='performance'?stage()+overlay():shell((views[state.screen]||home)());applyMotion();updateDynamic();if(state.overlay)setTimeout(()=>$('.modal button')?.focus(),0)}
function applyMotion(){let style=$('#motion-style');if(!style){style=document.createElement('style');style.id='motion-style';document.head.append(style)}style.textContent=state.settings.reducedMotion?'*,*:before,*:after{animation:none!important;transition:none!important}':''}
function navigate(screen){if(state.screen==='performance')return;if(state.countdown!==null){clearInterval(countdownTimer);state.countdown=null;roundBusy=false}state.screen=screen;render();snapshot(true);window.scrollTo(0,0)}
function pickNext(){state.singer=state.participants[0]||null;if(!state.singer){navigate('participants');toast('Add or select a singer to take the microphone.');return}state.demo=!state.song.reference.frames.length;state.screen='ready';state.countdown=null;render();snapshot(true)}
async function connectMic(){
 if(!navigator.mediaDevices?.getUserMedia)throw new Error('Open this app on localhost or HTTPS to use the microphone.');
 disconnectMic();state.mic='connecting';
 try{
  await ensureAudio();stream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:state.settings.deviceId?{exact:state.settings.deviceId}:undefined,echoCancellation:false,noiseSuppression:false,autoGainControl:false},video:false});
  await context.audioWorklet.addModule('pitch-worklet.js?v=2');
  sourceNode=context.createMediaStreamSource(stream);worklet=new AudioWorkletNode(context,'lev-pitch');silentGain=context.createGain();silentGain.gain.value=0;sourceNode.connect(worklet);worklet.connect(silentGain).connect(context.destination);
  smoother=new PitchSmoother();pitchWorker=new Worker('pitch-worker.js?v=2',{type:'module'});
  worklet.port.onmessage=e=>pitchWorker?.postMessage(e.data,[e.data.samples.buffer]);
  pitchWorker.onmessage=e=>{
   const {hz,rms,confidence,captureTime}=e.data;state.rms=rms;state.confidence=confidence;
   const threshold=state.midi!==null?.6:.68;
   state.midi=hz&&confidence>=threshold&&rms>=state.settings.noiseFloor?69+12*Math.log2(hz/440):null;
   displayMidi=smoother.push(state.midi,captureTime);lastPitch=performance.now();
   if(state.screen==='performance'&&!state.paused){updateTimeline();const t=timeline.captureAt(captureTime,state.settings.latency);micHistory.push({t,midi:state.midi});if(micHistory.length>500)micHistory.shift();displayPlotMidi=registerPitch(displayMidi,t);if(Number.isFinite(displayMidi))trace.push({t,midi:displayMidi,plotMidi:displayPlotMidi});trace=trace.filter(p=>p.t>state.time-7)}
  };
  pitchWorker.onerror=()=>{state.mic='error';state.midi=null;displayMidi=null;if(state.screen==='performance'&&!state.demo)pauseRound();toast('Microphone processing stopped. Reconnect the microphone.')};
  stream.getAudioTracks()[0].onended=()=>{state.mic='off';state.midi=null;displayMidi=null;if(state.screen==='performance'&&!state.demo){pauseRound();toast('Microphone disconnected. Reconnect before resuming.')}else render()};
  state.mic='ready';devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='audioinput');
 }catch(error){disconnectMic();state.mic='error';throw new Error(error.name==='NotAllowedError'?'Microphone access was declined. Allow access in your browser, then connect again.':error.name==='NotFoundError'?'No microphone found. Connect the USB mic and try again.':error.message)}
}
function disconnectMic(){if(stream)for(const track of stream.getTracks()){track.onended=null;track.stop()}if(worklet)worklet.port.onmessage=null;worklet?.disconnect();sourceNode?.disconnect();silentGain?.disconnect();pitchWorker?.terminate();stream=null;worklet=null;pitchWorker=null;state.mic='off';state.midi=null;displayMidi=null;state.rms=0;micHistory=[]}
function updateMic(){const meter=$('#mic-meter'),reading=$('#mic-reading');if(meter)meter.style.width=Math.min(100,state.rms*450)+'%';if(reading&&state.mic==='ready')reading.textContent=state.midi?`Connected · ${Math.round(440*2**((state.midi-69)/12))} Hz · input ${Math.round(state.rms*100)}%`:'Connected · listening for a clear voice';}
async function beginRound(){if(roundBusy||state.countdown!==null)return;roundBusy=true;try{await ensureAudio();if(!state.demo&&state.mic!=='ready')await connectMic();audio.src=state.song.instrumental;audio.volume=state.settings.volume;await new Promise((resolve,reject)=>{if(audio.readyState>=2){resolve();return}audio.oncanplay=()=>resolve();audio.onerror=()=>reject(new Error('The instrumental could not be loaded. Re-import the audio file.'));audio.load()});state.countdown=3;render();snapshot(true);countdownTimer=setInterval(()=>{state.countdown--;updateDynamic();snapshot();if(state.countdown<=0){clearInterval(countdownTimer);startPlayback()}},1000)}catch(e){toast(e.message);state.countdown=null;roundBusy=false;render()}}
async function startPlayback(){state.countdown=null;state.score=0;state.time=0;state.streak=0;state.bestStreak=0;state.accuracy=0;state.covered=0;state.paused=false;state.overlay=null;state.result=null;creditSum=0;voicedCount=0;scoreIndex=0;totalReference=state.song.reference.frames.length;micHistory=[];trace=[];smoother=new PitchSmoother();pitchRegister=new PitchRegister();audio.currentTime=0;try{await audio.play();updateTimeline();state.screen='performance';render();snapshot(true)}catch(e){toast('Playback did not start. Press Start singing again.');state.screen='ready';render()}roundBusy=false}
function pauseRound(){if(state.screen!=='performance')return;state.time=displayTime();audio.pause();updateTimeline();state.paused=true;state.overlay=true;render();snapshot()}
async function resume(){if(!state.demo&&state.mic!=='ready'){toast('Reconnect the microphone before resuming.');return}await context?.resume();try{await audio.play();updateTimeline();micHistory=[];state.paused=false;state.overlay=null;render();snapshot()}catch{toast('Playback could not resume. Check audio output and try again.')}}
function finish(completed){if(state.screen!=='performance')return;audio.pause();state.overlay=null;state.paused=false;const elapsedRef=scoreIndex||1;const result={id:crypto.randomUUID(),singer:{...state.singer},songId:state.song.id,songTitle:state.song.title,score:state.song.reference.frames.length?finalScore(creditSum*.02,totalReference*.02):0,accuracy:Math.round(100*creditSum/elapsedRef),coverage:Math.round(100*voicedCount/elapsedRef),bestStreak:state.bestStreak,duration:state.time,completed,demo:state.demo,createdAt:new Date().toISOString(),scoringVersion:'school-v2',profile:{octave:state.settings.octave,tolerance:state.settings.tolerance,latency:state.settings.latency,noiseFloor:state.settings.noiseFloor,...songTiming(),referenceVersion:state.song.reference.version||1},referenceReviewed:state.song.reference.reviewed};state.result=result;if(completed&&!state.demo){state.results.push(result);persist();result.rank=rankings().findIndex(r=>r.singer.id===result.singer.id)+1}state.screen='results';render();snapshot(true)}
audio.addEventListener('ended',()=>finish(true));audio.addEventListener('error',()=>{if(state.screen==='performance'){pauseRound();toast('Audio playback stopped. Check the song file before continuing.')}});
function scoreTick(){if(state.screen!=='performance'||state.paused||audience)return;updateTimeline();state.time=displayTime();const frames=state.song.reference.frames,melodyTime=state.time-songTiming().melody;
 const target=frames.length?frames[closestFrameIndex(frames,melodyTime)]:null;
 if(state.demo){state.midi=target&&Math.abs(target.t-melodyTime)<.05?target.midi+.4*Math.sin(melodyTime*4):null;displayMidi=smoother.push(state.midi,melodyTime);displayPlotMidi=registerPitch(displayMidi,state.time);if(Number.isFinite(displayMidi))trace.push({t:state.time,midi:displayMidi,plotMidi:displayPlotMidi})}
 else if(performance.now()-lastPitch>200){state.midi=null;displayMidi=null}
 while(scoreIndex<frames.length&&frames[scoreIndex].t<=melodyTime-.16){const reference=frames[scoreIndex];let midi=null;
  if(state.demo)midi=reference.midi+.4*Math.sin(reference.t*4);
  else{let nearest=null;const expectedTime=reference.t+songTiming().melody;for(const sample of micHistory)if(!nearest||Math.abs(sample.t-expectedTime)<Math.abs(nearest.t-expectedTime))nearest=sample;if(nearest&&Math.abs(nearest.t-expectedTime)<.055)midi=nearest.midi}
  const {credit}=scoreFrame(frames,reference.t,midi,{octave:state.settings.octave,tolerance:state.settings.tolerance});creditSum+=credit;if(Number.isFinite(midi))voicedCount++;state.streak=credit>=.8?state.streak+1:0;state.bestStreak=Math.max(state.bestStreak,Math.floor(state.streak*(state.song.reference.hopSeconds||.02)/.1));scoreIndex++;
 }
 state.score=finalScore(creditSum,totalReference);state.accuracy=scoreIndex?Math.round(100*creditSum/scoreIndex):0;state.covered=scoreIndex?Math.round(100*voicedCount/scoreIndex):0;
 trace=trace.filter(p=>state.time-p.t<7);if(performance.now()-lastSend>40){snapshot();lastSend=performance.now()}
}
function updateDynamic(){if(state.screen==='ready'){const h=$('#ready-heading');if(h){h.textContent=state.countdown??'GET READY.';h.classList.toggle('countdown',state.countdown!==null)}return}if(state.screen!=='performance')return;paintTime=displayTime();const timing=audience?state.remoteTiming||{lyrics:0,melody:0}:songTiming();const lyricTime=paintTime-timing.lyrics;const melodyTime=paintTime-timing.melody;const set=(selector,text)=>{const e=$(selector);if(e)e.textContent=text};set('#live-score',state.score.toLocaleString());set('#elapsed',format(paintTime));set('#remaining','−'+format(state.song.duration-paintTime));set('#live-accuracy',scoreIndex||audience?state.accuracy+'%':'—');set('#live-streak',Math.floor(state.streak*(state.song.reference.hopSeconds||.02)/.1)+' ✦');$('#song-progress').style.width=Math.min(100,100*paintTime/state.song.duration)+'%';$('#paused-sign').classList.toggle('hidden',!state.paused);
 const lines=state.song.lyrics;let idx=-1;for(let i=0;i<lines.length;i++)if(lines[i].start<=lyricTime)idx=i;const current=lines[idx],active=current&&lyricTime<current.end;const lyric=active?current.text:idx<0?'Get ready to sing…':idx===lines.length-1?'You made this moment yours.':'Instrumental · breathe and get ready';const el=$('#current-lyric');if(el.dataset.text!==lyric){el.innerHTML=`<span>${esc(lyric)}</span>`;el.dataset.text=lyric}el.style.setProperty('--fill',active?`${Math.min(100,100*(lyricTime-current.start)/(current.end-current.start))}%`:'0%');set('#next-lyric',lines[idx+1]?.text||(active?'Give the final phrase your voice.':'Take a bow.'));set('#section-label',active?'FOLLOW THE MELODY':'INSTRUMENTAL');
 const frames=state.song.reference.frames,target=frames.length?frames[closestFrameIndex(frames,melodyTime)]:null;let feedback='LISTEN FOR YOUR CUE';if(target&&Math.abs(target.t-melodyTime)<.04){const credit=scoreFrame(frames,melodyTime,state.midi,{octave:state.settings.octave,tolerance:state.settings.tolerance}).credit;feedback=state.midi===null?'SING INTO THE MIC':credit>=.8?'RIGHT ON MELODY ✦':credit>=.3?'KEEP FOLLOWING':'FIND THE YELLOW NOTES'}set('#accuracy-feedback',feedback);drawPitch();}
function drawPitch(){const canvas=$('#pitch');if(!canvas)return;const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1,w=rect.width,h=rect.height;if(canvas.width!==Math.floor(w*dpr)||canvas.height!==Math.floor(h*dpr)){canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr)}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const now=paintTime,melodyOffset=(audience?state.remoteTiming: songTiming())?.melody||0,referenceNow=now-melodyOffset,windowSeconds=9,marker=w*.27,px=w/windowSeconds;let notes=state.song.reference.notes.filter(n=>n.end>referenceNow-2.5&&n.start<referenceNow+6.5);const all=state.song.reference.notes.length?state.song.reference.notes.map(n=>n.midi):[55,72];let low=Math.min(...all)-3,high=Math.max(...all)+3;if(high-low<12){low-=3;high+=3}const y=m=>h-30-(m-low)/(high-low)*(h-60);for(let midi=Math.ceil(low);midi<=high;midi++){const yy=y(midi);c.strokeStyle=midi%12===0?'#48679750':'#36547a30';c.lineWidth=1;c.beginPath();c.moveTo(0,yy);c.lineTo(w,yy);c.stroke();if(midi%2===0){c.fillStyle='#819bc3';c.font='10px system-ui';c.fillText(['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][((midi%12)+12)%12],9,yy-4)}}
 const gradient=c.createLinearGradient(marker,0,w,0);gradient.addColorStop(0,'#ffd447');gradient.addColorStop(1,'#fce48a');for(const n of notes){if(n.end-n.start<.10)continue;const x=marker+(n.start+melodyOffset-now)*px,width=Math.max(5,(n.end-n.start)*px);c.globalAlpha=n.end<referenceNow?.3:1;c.fillStyle=gradient;c.shadowBlur=n.start<=referenceNow&&n.end>=referenceNow?15:0;c.shadowColor='#ffd447';c.beginPath();c.roundRect(x,y(n.midi)-5,width,10,4);c.fill()}c.globalAlpha=1;c.shadowBlur=0;const contour=state.song.reference.contour||state.song.reference.frames;let preceding=null;c.beginPath();for(const point of contour){if(point.t<referenceNow-2.5)continue;if(point.t>referenceNow+6.5)break;const x=marker+(point.t+melodyOffset-now)*px,yy=y(point.midi);if(preceding&&point.t-preceding.t<.24&&Math.abs(point.midi-preceding.midi)<4)c.lineTo(x,yy);else c.moveTo(x,yy);preceding=point}c.strokeStyle='#ffd447';c.lineWidth=7;c.lineJoin='round';c.lineCap='round';c.globalAlpha=.65;c.stroke();c.globalAlpha=1;c.strokeStyle='#83b0ff';c.lineWidth=1.5;c.beginPath();c.moveTo(marker,0);c.lineTo(marker,h);c.stroke();c.fillStyle='#a4c9ff';c.font='bold 9px system-ui';c.fillText('NOW',marker-11,18);
 c.strokeStyle='#7daeff';c.lineWidth=3;c.shadowColor='#5b9eff';c.shadowBlur=10;c.beginPath();let prev=null;for(const p of trace){const x=marker+(p.t-now)*px,yy=y(p.plotMidi??p.midi);if(prev&&p.t-prev.t<.14)c.lineTo(x,yy);else c.moveTo(x,yy);prev=p}c.stroke();if(displayMidi!==null){const yy=y(displayPlotMidi??displayMidi);c.fillStyle='#dcecff';c.beginPath();c.arc(marker,yy,6,0,Math.PI*2);c.fill();c.strokeStyle='#7daeff';c.lineWidth=2;c.stroke()}c.shadowBlur=0;if(!notes.length){c.fillStyle='#9fb4d6';c.font='13px system-ui';c.textAlign='center';c.fillText(state.song.reference.frames.length?'Your next notes are on the way…':'Practice song · no reference pitch imported',w/2,h/2);c.textAlign='left'}}
function animate(t){if(t-lastScoreTick>15){scoreTick();lastScoreTick=t}updateDynamic();if(t-lastMeter>70){updateMic();lastMeter=t}requestAnimationFrame(animate)}
app.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;try{
 if(action.startsWith('nav:'))navigate(action.slice(4));else if(action==='welcome')navigate('welcome');else if(action==='quick')pickNext();else if(action==='demo'){state.demo=true;state.singer={id:'demo',name:'Preview singer',className:'Gameplay rehearsal'};navigate('ready')}
 else if(action.startsWith('song:')){state.song=state.songs.find(s=>s.id===action.slice(5));pickNext()}
 else if(action.startsWith('singer:')){state.singer=state.participants.find(p=>p.id===action.slice(7));state.demo=!state.song.reference.frames.length;navigate('ready')}
 else if(action.startsWith('remove:')){state.participants=state.participants.filter(p=>p.id!==action.slice(7));persist();render()}
 else if(action.startsWith('timing:')){const [,kind,amount]=action.split(':');const timing=songTiming();timing[kind]=Math.max(-2,Math.min(2,timing[kind]+Number(amount)/1000));state.settings.songTiming[state.song.id]=timing;persist();render();snapshot(true)}else if(action==='start')await beginRound();else if(action==='pause')pauseRound();else if(action==='resume')await resume();else if(action==='reconnect'){await connectMic();render();toast('Microphone reconnected. Resume when ready.')}
 else if(action==='restart'){audio.pause();state.overlay=null;state.screen='ready';state.countdown=null;render();snapshot(true)}else if(action==='end')finish(false);else if(action==='again')navigate('ready');
 else if(action==='next'){if(state.result&&!state.result.demo&&state.result.completed){state.participants=state.participants.filter(p=>p.id!==state.result.singer.id);persist()}pickNext()}
 else if(action==='audience'){const popup=window.open(location.pathname+'?audience=1','lev-audience','popup,width=1280,height=720');if(!popup)toast('Allow popups for the audience display, then try again.');else toast('Move the audience window to the projector and press F for fullscreen.')}
 else if(action==='connect-mic'){state.settings.deviceId=$('#mic-device').value;persist();await connectMic();render();toast('Microphone connected. Sing a steady vowel to check input.')}
 else if(action==='disconnect-mic'){disconnectMic();render()}
 else if(action==='calibrate'){if(state.mic!=='ready'){toast('Connect the microphone first.');return}target.disabled=true;target.textContent='Stay quiet… measuring';const readings=[];const timer=setInterval(()=>readings.push(state.rms),50);setTimeout(()=>{clearInterval(timer);readings.sort((a,b)=>a-b);state.settings.noiseFloor=Math.max(.0015,Math.min(.03,(readings[Math.floor(readings.length*.8)]||.001)*1.35));persist();if(state.screen==='settings')render();toast('Room noise measured. Try singing to check the input.')},3000)}
 else if(action==='save-event'){state.settings.eventName=$('#event-name').value.trim()||'Lev Vigotsky Karaoke';persist();render();snapshot();toast('Event name saved.')}
 else if(action==='export')exportCSV();else if(action==='backup')download('lev-voice-event-backup.json',JSON.stringify({version:1,participants:state.participants,performances:state.results,settings:state.settings},null,2),'application/json');
 }catch(error){toast(error.message)}});
app.addEventListener('input',e=>{const id=e.target.id;if(id==='voice-sensitivity'){state.settings.noiseFloor=.0008*Math.pow(37.5,1-Number(e.target.value)/100);$('#sensitivity-value').textContent=e.target.value+'%';$('#noise-value').textContent=state.settings.noiseFloor.toFixed(4);persist()}if(id==='lyrics-offset'||id==='melody-offset'){const timing=songTiming();timing[id==='lyrics-offset'?'lyrics':'melody']=Number(e.target.value)/1000;state.settings.songTiming[state.song.id]=timing;$('#'+id+'-value').textContent=e.target.value+' ms';persist();snapshot(true)}if(id==='song-search')$('#song-grid').innerHTML=songCards(state.songs.filter(s=>(s.title+' '+s.artist).toLowerCase().includes(e.target.value.toLowerCase())));if(id==='volume'){state.settings.volume=+e.target.value;audio.volume=state.settings.volume;$('#volume-value').textContent=Math.round(state.settings.volume*100)+'%';persist()}if(id==='latency'){state.settings.latency=+e.target.value;$('#latency-value').textContent=e.target.value+' ms';persist()}});
app.addEventListener('change',e=>{if(e.target.id==='octave')state.settings.octave=e.target.checked;if(e.target.id==='tolerance')state.settings.tolerance=+e.target.value;if(e.target.id==='reduced-motion'){state.settings.reducedMotion=e.target.checked;applyMotion()}persist()});
app.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='participant-form'){const name=$('#singer-name').value.trim(),className=$('#singer-class').value.trim();if(!name||!className)return;state.participants.push({id:crypto.randomUUID(),name,className});persist();render();toast('Singer added to the queue.')}if(e.target.id==='import-form')try{await importSong()}catch(error){toast(error.message)}});
async function importSong(){const audioFile=$('#import-audio').files[0],lrc=$('#import-lrc').files[0],refFile=$('#import-reference').files[0];if(!audioFile||!lrc)return;const url=URL.createObjectURL(audioFile),probe=new Audio(url);try{await new Promise((resolve,reject)=>{probe.onloadedmetadata=resolve;probe.onerror=()=>reject(new Error('This audio format could not be opened. Try MP3 or WAV.'))});let ref={frames:[],notes:[],reviewed:false};if(refFile){const json=JSON.parse(await refFile.text());ref=json.reference||json;if(!Array.isArray(ref.frames)||!Array.isArray(ref.notes)||!ref.frames.length||!ref.notes.length)throw new Error('Reference JSON needs nonempty frames and notes arrays.');for(const f of ref.frames)if(!Number.isFinite(f.t)||!Number.isFinite(f.midi)||f.t<0||f.t>probe.duration)throw new Error('Reference frames contain invalid timing or pitch.');for(const n of ref.notes)if(!Number.isFinite(n.start)||!Number.isFinite(n.end)||!Number.isFinite(n.midi)||n.start<0||n.end<=n.start||n.end>probe.duration+.1)throw new Error('Reference notes contain invalid timing or pitch.');ref.frames.sort((a,b)=>a.t-b.t)}const lyrics=parseLrc(await lrc.text(),probe.duration);if(!lyrics.length)throw new Error('No timed lyric lines found. Use [mm:ss.xx]line text in the LRC file.');const song={id:crypto.randomUUID(),title:$('#import-title').value.trim(),artist:$('#import-artist').value.trim(),instrumental:url,duration:probe.duration,language:'English',lyrics,reference:ref,lyricPrecision:'line'};state.songs.push(song);state.song=song;navigate('management');toast('Song imported for this session.')}catch(error){URL.revokeObjectURL(url);throw error}}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const cell=v=>{let value=String(v??'');if(/^[=+@-]/.test(value))value="'"+value;return '"'+value.replace(/"/g,'""')+'"'};download('lev-voice-results.csv',[['Singer','Class','Song','Score','Accuracy %','Voice coverage %','Best streak','Completed','Timestamp'],...state.results.map(r=>[r.singer.name,r.singer.className,r.songTitle,r.score,r.accuracy,r.coverage,r.bestStreak,r.completed,r.createdAt])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='f'){e.preventDefault();if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('Fullscreen is unavailable in this browser.'));return}if(audience)return;if(state.screen==='performance'&&(e.code==='Space'||e.key==='Escape')){e.preventDefault();if(state.paused&&e.code==='Space')resume();else pauseRound()}if(state.screen==='results'&&e.key.toLowerCase()==='n')$('[data-action="next"]')?.click()});
window.addEventListener('beforeunload',e=>{if(!audience&&state.screen==='performance'){e.preventDefault();e.returnValue=''}});
try{const response=await fetch('assets/song.json?v=2');if(!response.ok)throw new Error('Song package missing');state.songs=[await response.json()];state.song=state.songs[0];render();if(audience)channel.postMessage({type:'hello'});requestAnimationFrame(animate)}catch(error){app.innerHTML=`<div class="loading"><div>LEV <span>VOICE</span></div><p>${esc(error.message)}. Serve the dist folder using the included launcher.</p></div>`}
